ga_g(){return"\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0639\u0631\u0636"},
ga_f(){return"\u0646\u0634\u0637"},
gYO(){return"\u0627\u0644\u0627\u0633\u0645"},
gYN(){return"\u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u0643\u0648\u0651\u0646\u0629"},
gYP(){return"\u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629"},
