YA(a,b){var s=null,r=this.a
return A.b3(a,s,r,s,"\u0645\u0627\u062f\u0629 \u0648\u0627\u062d\u062f\u0629",""+a+" \u0645\u0627\u062f\u0629",s,s)+" \xb7 "+A.b3(b,s,r,s,"\u0645\u0631\u062d\u0644\u0629 \u0648\u0627\u062d\u062f\u0629",""+b+" \u0645\u0631\u062d\u0644\u0629",s,s)+" \u0641\u064a \u062e\u0637 \u0627\u0644\u0625\u0646\u062a\u0627\u062c"},
gYX(){return"\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062a\u0641\u0639\u064a\u0644"},
gYn(){return"\u062a\u0641\u0639\u064a\u0644"},
gZ0(){return"\u062d\u0630\u0641 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0646\u0647\u0627\u0626\u064a\u064b\u0627"},
gZ_(){return"\u0647\u0644 \u062a\u0631\u064a\u062f \u062d\u0630\u0641 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0647\u0630\u0627 \u0646\u0647\u0627\u0626\u064a\u064b\u0627\u061f"},
YY(a){return"\u0633\u064a\u062a\u0645 \u062d\u0630\u0641 "+a+" \u0646\u0647\u0627\u0626\u064a\u064b\u0627 \u0645\u0639 \u0645\u0648\u0627\u062f\u0651\u0647 \u0648\u062f\u0631\u062c\u0627\u062a \u0623\u0644\u0648\u0627\u0646\u0647 \u0648\u062e\u0635\u0627\u0626\u0635\u0647 \u0648\u0645\u0633\u0627\u0631\u0647 \u0627\u0644\u0625\u0646\u062a\u0627\u062c\u064a\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0630\u0644\u0643. \u064a\u064f\u0633\u0645\u062d \u0628\u0630\u0644\u0643 \u0641\u0642\u0637 \u0625\u0630\u0627 \u0644\u0645 \u064a\u0643\u0646 \u0644\u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0623\u064a \u062d\u0627\u0644\u0627\u062a\u060c \u0623\u0648 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0641\u0631\u0639 \u0644\u0627 \u064a\u0632\u0627\u0644 \u062c\u062f\u064a\u062f\u064b\u0627 \u2014 \u0648\u0625\u0644\u0627\u060c \u0642\u0645 \u0628\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062a\u0641\u0639\u064a\u0644 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0630\u0644\u0643."},
gYZ(){return"\u062a\u0645 \u062d\u0630\u0641 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0646\u0647\u0627\u0626\u064a\u064b\u0627."},
gZJ(){return"\u0627\u0644\u0645\u0648\u0627\u062f"},
gGk(){return"\u0625\u0636\u0627\u0641\u0629 \u0645\u0627\u062f\u0629"},
gGp(){return"\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0645\u0627\u062f\u0629"},
gZs(){return"\u0627\u0644\u0627\u0633\u0645"},
Zx(a){return"\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a ("+a+")"},
Zk(a){return"\u0627\u0644\u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 ("+a+")"},
ZQ(a,b){return a+" "+b},
YV(a,b){return"\u0627\u0644\u062a\u0643\u0644\u0641\u0629 "+a+" "+b},
ZR(a,b){return a+" "+b+"/\u0648\u062d\u062f\u0629"},
YW(a,b){return"\u0627\u0644\u062a\u0643\u0644\u0641\u0629 "+a+" "+b+"/\u0648\u062d\u062f\u0629"},
