ga2H(){return"\u062e\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0646\u06cc \u0646\u0631\u062e\u06cc \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u0645\u0627\u062f\u062f\u06d5\u06a9\u06d5. \u0646\u0631\u062e\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u0627\u0648 \u062a\u06d5\u0646\u0647\u0627 \u0628\u06c6 \u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u062f\u06d5\u0628\u06ce\u062a."},
a2G(a){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc "+a},
ga2K(){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc"},
ga2J(){return"\u06cc\u06d5\u06a9\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u0645"},
ga2F(){return"\u06cc\u06d5\u06a9\u06d5\u06cc \u0632\u06cc\u0627\u062a\u0631"},
ga2P(){return"\u0646\u0631\u062e\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u06d5 \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5 \u067e\u06ce\u0634\u0648\u0648\u06d5\u06a9\u0627\u0646 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u0628\u06a9\u0631\u06ce\u062a\u061f"},
a2N(a){return""+a+" \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u0646\u0631\u062e\u06cc\u0627\u0646 \u062f\u06d5\u06af\u06c6\u0695\u06ce\u062a \u0628\u06d5 \u0646\u0631\u062e\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u06d5. \u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0644\u0627\u0628\u06d5 \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0646\u0631\u062e\u06cc \u0626\u06ce\u0633\u062a\u0627\u06cc \u0628\u0645\u06ce\u0646\u06ce\u062a. \u06a9\u06d5\u06cc\u0633\u06cc \u067e\u0627\u0631\u06d5\u062f\u0631\u0627\u0648\u060c \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5 \u0648 \u0647\u06d5\u06b5\u0648\u06d5\u0634\u0627\u0648\u06d5 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0646\u0627\u06af\u06c6\u0695\u06ce\u0646."},
ga2O(){return"\u062a\u06d5\u0646\u0647\u0627 \u06a9\u06d5\u06cc\u0633\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u0627\u0646"},
a2L(a){return"\u0646\u0648\u06ce\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc "+a+" \u06a9\u06d5\u06cc\u0633"},
a2M(a){return"\u0646\u0631\u062e\u06cc "+a+" \u06a9\u06d5\u06cc\u0633 \u0646\u0648\u06ce\u06a9\u0631\u0627\u06cc\u06d5\u0648\u06d5"},
a3L(a){return"\u0646\u06cc\u0633\u0628\u06d5\u06a9\u0627\u0646 \u2014 "+a},
a3K(a){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc "+a+"/\u06cc\u06d5\u06a9\u06d5"},
ga3P(){return"\u06af\u06d5\u0695\u0627\u0646\u06d5\u0648\u06d5 \u0628\u06c6 \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc"},
ga3J(){return"\u0628\u06d5\u067e\u06ce\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
ga3M(){return"\u062e\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0646\u06cc \u0646\u0631\u062e\u06cc \u0626\u0627\u0633\u0627\u06cc\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5. \u0628\u0695\u06ce\u06a9 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 2000) \u06cc\u0627\u0646 \u0695\u06ce\u0698\u06d5\u06cc\u06d5\u06a9 \u0644\u06d5 \u0646\u0631\u062e\u06cc \u06a9\u06d5\u06cc\u0633 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 60%) \u0628\u0646\u0648\u0648\u0633\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u0628\u06c6 \u0626\u06d5\u0645 \u062c\u06c6\u0631\u06d5."},
ga3O(){return"\u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0628\u06d5 \u0695\u06ce\u0698\u06d5 \u062d\u06cc\u0633\u0627\u0628 \u062f\u06d5\u06a9\u0631\u06ce\u062a\u060c \u0628\u06c6\u06cc\u06d5 \u0628\u0695 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9 \u0644\u06ce\u0631\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u0646\u0627\u0628\u06ce\u062a - \u0695\u06ce\u0698\u06d5 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 60%)."},
gHs(){return"\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 2000 \u06cc\u0627\u0646 60%"},
ga3I(){return"\u0628\u06c6 \u0647\u06d5\u0631 \u0634\u06d5\u0648\u06cc\u0644\u06af\u06d5\u06cc\u06d5\u06a9"},
ga3N(){return"\u0628\u0695\u06ce\u06a9 \u06cc\u0627\u0646 \u0695\u06ce\u0698\u06d5\u06cc\u06d5\u06a9 \u0628\u0646\u0648\u0648\u0633\u06d5"},
ga43(){return"\u0628\u06d5\u067e\u06ce\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
ga42(){return"\u06cc\u0627\u0633\u0627\u06cc \u067e\u0632\u06cc\u0634\u06a9 \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0648 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u06ce\u062a \u0648 \u0644\u06d5 \u0646\u0631\u062e\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u062e\u0648\u0627\u0631\u06d5\u0648\u06d5 \u0644\u06d5 \u067e\u06ce\u0634\u062a\u0631\u06d5."},
ga41(){return"\u0647\u06cc\u0686 \u06cc\u0627\u0633\u0627\u06cc\u06d5\u06a9\u06cc \u067e\u0632\u06cc\u0634\u06a9 \u0646\u06cc\u06cc\u06d5."},
ga40(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u06cc\u0627\u0633\u0627\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
