DI(a){var s=null
return A.b3(a,s,this.a,s,"1 \u062c\u06c6\u0631",""+a+" \u062c\u06c6\u0631",s,s)},
ga7c(){return"\u0633\u06a9\u0627\u0646\u06a9\u0631\u062f\u0646\u06cc \u0628\u0627\u0631\u06a9\u06c6\u062f\u06cc \u0642\u0648\u062a\u0648\u0648\u06cc \u06a9\u0627\u06b5\u0627 \u06cc\u06d5\u06a9 \u0642\u0648\u062a\u0648\u0648 \u0644\u06d5 \u06a9\u06c6\u06af\u0627 \u0628\u06d5 \u0646\u0627\u0648\u06cc \u062a\u06c6\u0648\u06d5 \u062f\u06d5\u0631\u062f\u06d5\u0647\u06ce\u0646\u06ce\u062a."},
ga7d(){return"\u0626\u06d5\u0645 \u0628\u0627\u0631\u06a9\u06c6\u062f\u06d5 \u0647\u06ce\u0634\u062a\u0627 \u0628\u06d5 \u0647\u06cc\u0686 \u06a9\u0627\u06b5\u0627\u06cc\u06d5\u06a9\u06cc \u06a9\u06c6\u06af\u0627\u0648\u06d5 \u0646\u06d5\u0628\u06d5\u0633\u062a\u0631\u0627\u0648\u06d5 \u2014 \u062f\u0627\u0648\u0627 \u0644\u06d5 \u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631 \u0628\u06a9\u06d5 \u0628\u06cc\u0628\u06d5\u0633\u062a\u06ce\u062a\u06d5\u0648\u06d5."},
