ga7f(){return"\u067e\u0627\u0634\u06af\u06d5\u0632\u06a9\u0631\u0627\u06cc\u06d5\u0648\u06d5 \u2014 \u0642\u0648\u062a\u0648\u0648\u06d5\u06a9\u06d5 \u06af\u06d5\u0695\u0627\u06cc\u06d5\u0648\u06d5 \u0628\u06c6 \u06a9\u06c6\u06af\u0627."},
gPM(){return"\u0695\u06d5\u0646\u06af / \u0642\u06d5\u0628\u0627\u0631\u06d5\u06cc \u062c\u06cc\u0627\u0648\u0627\u0632\u061f"},
gQ1(){return"\u0626\u06d5\u0645 \u0642\u0648\u062a\u0648\u0648\u06d5 \u0647\u06cc \u06a9\u0627\u0645 \u06a9\u0627\u06b5\u0627\u06cc\u06d5\u061f"},
gQ0(){return"\u0695\u06d5\u0646\u06af/\u0642\u06d5\u0628\u0627\u0631\u06d5\u06cc \u062f\u0631\u0648\u0633\u062a \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5\u060c \u0626\u06d5\u067e\u06d5\u06a9\u06d5 \u0644\u06d5\u0645\u06d5\u0648\u062f\u0648\u0627 \u062c\u06cc\u0627\u06cc \u062f\u06d5\u06a9\u0627\u062a\u06d5\u0648\u06d5."},
ga59(){return"\u062a\u06d5\u06a9\u0646\u06cc\u0634\u06cc\u0627\u0646\u06cc \u0633\u06a9\u06d5\u0646\u06d5\u0631"},
gCh(){return"\u0633\u06a9\u06d5\u0646\u06d5\u0631\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5"},
