ga8w(){return"\u062a\u0646\u06ce \u062a\u0648 \u062a\u06ce\u0628\u06cc\u0646\u06cc\u06ce\u0646 \u062e\u06c6 \u062f\u0628\u06cc\u0646\u06cc."},
ga8t(){return"\u0647\u06ce\u0634\u062a\u0627 \u0686 \u062a\u06ce\u0628\u06cc\u0646\u06cc \u0646\u06cc\u0646\u0646. \u0647\u06d5\u0631 \u062a\u0634\u062a\u06d5\u06a9\u06ce \u062a\u06d5 \u062f\u06a4\u06ce\u062a \u067e\u0627\u0634\u06cc \u0644 \u0633\u06d5\u0631 \u0628\u0632\u06a4\u0695\u06cc \u0628\u0646\u06a4\u06cc\u0633\u06d5."},
a8s(a){var s=null
return A.b3(a,s,this.a,s,"1 \u062f\u06d5\u0645\u06ce \u0648\u06ce \u0647\u0627\u062a",""+a+" \u062f\u06d5\u0645\u06ce \u0648\u0627\u0646 \u0647\u0627\u062a",s,s)},
